                g[r][c] = ink
            else:
                break

    for color, col_top in bars(g[0]):
        for color2, col_bottom in bars(g[-1]):
            if color == color2:
                cast((r, col_top) for r in range(1, h))
                cast((r, col_bottom) for r in range(h-2, -1, -1))
                return g

    left_bars = bars([g[r][0] for r in range(h)])
    right_bars = bars([g[r][-1] for r in range(h)])
